1	import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
2	import db from "~/db.server";
3	import { corsJson, corsOptions, validateShop } from "~/lib/api.server";
4	import { checkRateLimit } from "~/lib/rate-limit.server";
5	import { hasFeature } from "~/lib/plans";
6	import { recommendSize } from "~/lib/ai.server";
7	import type { RecommendInput } from "~/lib/ai.server";
8	
9	// ---------------------------------------------------------------------------
10	// Types
11	// ---------------------------------------------------------------------------
12	
13	type GenderInput = "male" | "female" | "unisex";
14	type BodyTypeInput = "slim" | "average" | "athletic" | "plus";
15	type BodyTypeCalc = "slim" | "regular" | "athletic" | "plus";
16	
17	interface RecommendRequestBody {
18	  shop: string;
19	  chartId: string;
20	  height: number;
21	  weight: number;
22	  unit: "metric" | "imperial";
23	  gender: GenderInput;
24	  bodyType: BodyTypeInput;
25	}
26	
27	interface ParsedChartData {
28	  headers: string[];
29	  units: { default: string; available: string[] };
30	  rows: Record<string, string>[];
31	}
32	
33	// ---------------------------------------------------------------------------
34	// Loader — handle OPTIONS preflight only
35	// ---------------------------------------------------------------------------
36	
37	export const loader = async ({ request }: LoaderFunctionArgs) => {
38	  if (request.method === "OPTIONS") {
39	    return corsOptions();
40	  }
41	  return corsJson({ error: "Method not allowed" }, { status: 405 });
42	};
43	
44	// ---------------------------------------------------------------------------
45	// Action — POST /api/recommend
46	// Body JSON: { shop, chartId, height, weight, unit, gender, bodyType }
47	// ---------------------------------------------------------------------------
48	
49	export const action = async ({ request }: ActionFunctionArgs) => {
50	  if (request.method === "OPTIONS") {
51	    return corsOptions();
52	  }
53	
54	  if (request.method !== "POST") {
55	    return corsJson({ error: "Method not allowed" }, { status: 405 });
56	  }
57	
58	  // Parse body
59	  let body: Partial<RecommendRequestBody>;
60	  try {
61	    body = (await request.json()) as Partial<RecommendRequestBody>;
62	  } catch {
63	    return corsJson({ error: "Invalid JSON body" }, { status: 400 });
64	  }
65	
66	  const { shop, chartId, height, weight, unit, gender, bodyType } = body;
67	
68	  // Validate shop
69	  const shopError = validateShop(shop ?? null);
70	  if (shopError) return shopError;
71	
72	  // Rate limit: 30 requests per minute per shop
73	  const rateLimitError = checkRateLimit(`recommend:${shop as string}`, 30);
74	  if (rateLimitError) return rateLimitError;
75	
76	  // Validate chartId
77	  if (!chartId) {
78	    return corsJson({ error: "chartId is required" }, { status: 400 });
79	  }
80	
81	  // Validate height
82	  if (typeof height !== "number" || height <= 0) {
83	    return corsJson({ error: "height must be a positive number" }, { status: 400 });
84	  }
85	
86	  // Validate weight
87	  if (typeof weight !== "number" || weight <= 0) {
88	    return corsJson({ error: "weight must be a positive number" }, { status: 400 });
89	  }
90	
91	  // Validate unit
92	  if (!unit || !["metric", "imperial"].includes(unit)) {
93	    return corsJson(
94	      { error: "unit must be 'metric' or 'imperial'" },
95	      { status: 400 },
96	    );
97	  }
98	
99	  // Validate gender
100	  if (!gender || !["male", "female", "unisex"].includes(gender)) {
101	    return corsJson(
102	      { error: "gender must be 'male', 'female', or 'unisex'" },
103	      { status: 400 },
104	    );
105	  }
106	
107	  // Validate bodyType
108	  if (!bodyType || !["slim", "average", "athletic", "plus"].includes(bodyType)) {
109	    return corsJson(
110	      { error: "bodyType must be 'slim', 'average', 'athletic', or 'plus'" },
111	      { status: 400 },
112	    );
113	  }
114	
115	  // Range validation — reject impossible measurements
116	  const isMetric = unit === "metric";
117	  const minHeight = isMetric ? 100 : 40;
118	  const maxHeight = isMetric ? 250 : 98;
119	  const minWeight = isMetric ? 30 : 66;
120	  const maxWeight = isMetric ? 300 : 660;
121	
122	  if (height < minHeight || height > maxHeight) {
123	    return corsJson(
124	      {
125	        error: `height must be between ${minHeight} and ${maxHeight} ${isMetric ? "cm" : "inches"}`,
126	      },
127	      { status: 400 },
128	    );
129	  }
130	  if (weight < minWeight || weight > maxWeight) {
131	    return corsJson(
132	      {
133	        error: `weight must be between ${minWeight} and ${maxWeight} ${isMetric ? "kg" : "lbs"}`,
134	      },
135	      { status: 400 },
136	    );
137	  }
138	
139	  try {
140	    // Check recommender is enabled for this shop
141	    const recommenderConfig = await db.recommenderConfig.findUnique({
142	      where: { shop: shop as string },
143	    });
144	
145	    if (!recommenderConfig?.enabled) {
146	      return corsJson(
147	        { error: "AI recommender is not enabled for this shop" },
148	        { status: 403 },
149	      );
150	    }
151	
152	    // Check subscription plan has aiRecommender feature
153	    const subscription = await db.subscription.findUnique({
154	      where: { shop: shop as string },
155	    });
156	    const planId = subscription?.planId ?? "free";
157	
158	    if (!hasFeature(planId, "aiRecommender")) {
159	      return corsJson(
160	        { error: "AI recommender requires a Growth or Pro plan" },
161	        { status: 403 },
162	      );
163	    }
164	
165	    // Fetch the chart scoped to this shop
166	    const chart = await db.sizeChart.findFirst({
167	      where: { id: chartId, shop: shop as string, status: "active" },
168	    });
169	
170	    if (!chart) {
171	      return corsJson({ error: "Chart not found" }, { status: 404 });
172	    }
173	
174	    // Parse chart data
175	    let parsedChart: ParsedChartData;
176	    try {
177	      const raw = JSON.parse(chart.data) as unknown;
178	      if (raw !== null && typeof raw === "object" && !Array.isArray(raw)) {
179	        const obj = raw as Record<string, unknown>;
180	        parsedChart = {
181	          headers: Array.isArray(obj.headers) ? (obj.headers as string[]) : [],
182	          units:
183	            obj.units !== null &&
184	            typeof obj.units === "object" &&
185	            !Array.isArray(obj.units)
186	              ? (obj.units as { default: string; available: string[] })
187	              : { default: "in", available: ["in", "cm"] },
188	          rows: Array.isArray(obj.rows)
189	            ? (obj.rows as Record<string, string>[])
190	            : [],
191	        };
192	      } else {
193	        parsedChart = {
194	          headers: [],
195	          units: { default: "in", available: ["in", "cm"] },
196	          rows: [],
197	        };
198	      }
199	    } catch {
200	      parsedChart = {
201	        headers: [],
202	        units: { default: "in", available: ["in", "cm"] },
203	        rows: [],
204	      };
205	    }
206	
207	    // Convert inputs to metric (cm / kg) — lib/ai.server always expects metric
208	    const heightCm: number = isMetric ? height : height * 2.54;
209	    const weightKg: number = isMetric ? weight : weight / 2.20462;
210	
211	    // Map "unisex" → "female" (neutral anthropometric default)
212	    const calcGender: "male" | "female" =
213	      gender === "male" ? "male" : "female";
214	
215	    // Map "average" → "regular" to match lib/ai.server body type vocabulary
216	    const calcBodyType: BodyTypeCalc =
217	      bodyType === "average" ? "regular" : bodyType;
218	
219	    const input: RecommendInput = {
220	      height: heightCm,
221	      weight: weightKg,
222	      gender: calcGender,
223	      bodyType: calcBodyType,
224	      chartData: {
225	        headers: parsedChart.headers,
226	        rows: parsedChart.rows,
227	      },
228	    };
229	
230	    const result = recommendSize(input);
231	
232	    return corsJson({
233	      recommendedSize: result.recommendedSize,
234	      confidence: result.confidence,
235	      alternatives: result.alternatives,
236	      // Expose as "measurements" to preserve the existing storefront widget contract
237	      measurements: result.estimatedMeasurements,
238	    });
239	  } catch (error) {
240	    console.error("[api.recommend]", error);
241	    return corsJson(
242	      { error: "Unable to process recommendation. Please try again." },
243	      { status: 500 },
244	    );
245	  }
246	};
