1	import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
2	import db from "../db.server";
3	import { corsOptions, corsJson, validateShop } from "../lib/api.server";
4	import { checkRateLimit } from "../lib/rate-limit.server";
5	
6	// ---------------------------------------------------------------------------
7	// Validation
8	// ---------------------------------------------------------------------------
9	
10	const VALID_EVENT_TYPES = [
11	  "view",
12	  "click",
13	  "recommend",
14	  "convert",
15	  "dismiss",
16	] as const;
17	
18	type EventType = (typeof VALID_EVENT_TYPES)[number];
19	
20	interface AnalyticsEventBody {
21	  shop: string;
22	  eventType: EventType;
23	  sizeChartId?: string;
24	  productId?: string;
25	  metadata?: Record<string, unknown>;
26	}
27	
28	const PRODUCT_ID_RE = /^(\d{1,20}|gid:\/\/shopify\/Product\/\d{1,20})$/;
29	const CHART_ID_RE = /^[a-z0-9]{1,30}$/;
30	
31	// ---------------------------------------------------------------------------
32	// Preflight
33	// ---------------------------------------------------------------------------
34	
35	export const loader = async ({ request }: LoaderFunctionArgs) => {
36	  if (request.method === "OPTIONS") {
37	    return corsOptions();
38	  }
39	  return corsJson({ error: "Method not allowed" }, { status: 405 });
40	};
41	
42	// ---------------------------------------------------------------------------
43	// Action — POST /api/analytics-event
44	// Body JSON: { shop, eventType, sizeChartId?, productId?, metadata? }
45	// ---------------------------------------------------------------------------
46	
47	export const action = async ({ request }: ActionFunctionArgs) => {
48	  if (request.method === "OPTIONS") {
49	    return corsOptions();
50	  }
51	
52	  if (request.method !== "POST") {
53	    return corsJson({ error: "Method not allowed" }, { status: 405 });
54	  }
55	
56	  let body: Partial<AnalyticsEventBody>;
57	
58	  try {
59	    body = (await request.json()) as Partial<AnalyticsEventBody>;
60	  } catch {
61	    return corsJson({ error: "Invalid JSON body" }, { status: 400 });
62	  }
63	
64	  const { shop, eventType, sizeChartId, productId, metadata } = body;
65	
66	  // Validate shop
67	  const shopError = validateShop(shop ?? null);
68	  if (shopError) return shopError;
69	
70	  // Rate limit keyed on shop — 300 events per minute
71	  const rateLimitError = checkRateLimit("analytics:" + shop!, 300);
72	  if (rateLimitError) return rateLimitError;
73	
74	  // Validate eventType
75	  if (
76	    !eventType ||
77	    !(VALID_EVENT_TYPES as readonly string[]).includes(eventType)
78	  ) {
79	    return corsJson(
80	      { error: `eventType must be one of: ${VALID_EVENT_TYPES.join(", ")}` },
81	      { status: 400 },
82	    );
83	  }
84	
85	  // Validate optional ID formats to prevent DB pollution
86	  if (productId !== undefined && productId !== null && !PRODUCT_ID_RE.test(productId)) {
87	    return corsJson({ error: "Invalid productId format" }, { status: 400 });
88	  }
89	  if (sizeChartId !== undefined && sizeChartId !== null && !CHART_ID_RE.test(sizeChartId)) {
90	    return corsJson({ error: "Invalid sizeChartId format" }, { status: 400 });
91	  }
92	
93	  // Fire-and-forget: respond immediately and write in the background
94	  // We still await to keep error handling consistent, but we return fast
95	  // because DB writes are non-blocking in practice at this scale
96	  try {
97	    const metadataRaw =
98	      metadata !== undefined && metadata !== null
99	        ? JSON.stringify(metadata)
100	        : "{}";
101	    // Clamp metadata size to prevent storage abuse
102	    const metadataJson = metadataRaw.length > 2048 ? "{}" : metadataRaw;
103	
104	    await db.analyticsEvent.create({
105	      data: {
106	        shop: shop!,
107	        eventType,
108	        sizeChartId: sizeChartId ?? null,
109	        productId: productId ?? null,
110	        metadata: metadataJson,
111	      },
112	    });
113	
114	    return corsJson({ ok: true });
115	  } catch {
116	    // Non-critical: tracking failures should not break the storefront
117	    // Still return 200 to avoid retries from the widget
118	    return corsJson({ ok: true });
119	  }
120	};
